B.bqp=new A.dU("Nox only knows the scams on its list. Check on the official number or app before you pay.","Nox \u0938\u093f\u0930\u094d\u092b\u093c \u0905\u092a\u0928\u0940 \u0932\u093f\u0938\u094d\u091f \u0935\u093e\u0932\u0947 \u0938\u094d\u0915\u0948\u092e \u092a\u0939\u091a\u093e\u0928\u0924\u093e \u0939\u0948\u0964 \u092a\u0948\u0938\u0947 \u0926\u0947\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0911\u092b\u093c\u093f\u0936\u093f\u092f\u0932 \u0928\u0902\u092c\u0930 \u092f\u093e \u0910\u092a \u092a\u0930 \u091c\u093e\u0902\u091a \u0932\u0947\u0902\u0964","Nox \u0932\u093e \u092b\u0915\u094d\u0924 \u0924\u094d\u092f\u093e\u091a\u094d\u092f\u093e \u092f\u093e\u0926\u0940\u0924\u0932\u0947 \u0938\u094d\u0915\u0945\u092e \u0913\u0933\u0916\u0924\u093e \u092f\u0947\u0924\u093e\u0924. \u092a\u0948\u0938\u0947 \u0926\u0947\u0923\u094d\u092f\u093e\u0906\u0927\u0940 \u0905\u0927\u093f\u0915\u0943\u0924 \u0928\u0902\u092c\u0930 \u0915\u093f\u0902\u0935\u093e \u0972\u092a\u0935\u0930 \u0916\u093e\u0924\u094d\u0930\u0940 \u0915\u0930\u093e.")
B.bqq=new A.dU("Red flags Nox found","Nox \u0915\u094b \u092e\u093f\u0932\u0947 \u0916\u0924\u0930\u0947 \u0915\u0947 \u0928\u093f\u0936\u093e\u0928","Nox \u0932\u093e \u0938\u093e\u092a\u0921\u0932\u0947\u0932\u0940 \u0927\u094b\u0915\u094d\u092f\u093e\u091a\u0940 \u091a\u093f\u0928\u094d\u0939\u0902")
