B.bqu=new A.dU("NO SUS is independent. Not affiliated with the Government of India.","NO SUS \u090f\u0915 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0910\u092a \u0939\u0948\u0964 \u092d\u093e\u0930\u0924 \u0938\u0930\u0915\u093e\u0930 \u0938\u0947 \u0938\u0902\u092c\u0926\u094d\u0927 \u0928\u0939\u0940\u0902\u0964","NO SUS \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0972\u092a \u0906\u0939\u0947. \u092d\u093e\u0930\u0924 \u0938\u0930\u0915\u093e\u0930\u0936\u0940 \u0938\u0902\u0932\u0917\u094d\u0928 \u0928\u093e\u0939\u0940.")
B.XQ=new A.dU("Make a SUS card","SUS \u0915\u093e\u0930\u094d\u0921 \u092c\u0928\u093e\u090f\u0902","SUS \u0915\u093e\u0930\u094d\u0921 \u092c\u0928\u0935\u093e")
B.bqv=new A.dU("Share the card","\u0915\u093e\u0930\u094d\u0921 \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902","\u0915\u093e\u0930\u094d\u0921 \u0936\u0947\u0905\u0930 \u0915\u0930\u093e")
